import{_ as o,l as i,o as a,c as s,v as r,p as n,x as l,d as p,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"参数服务器对照","description":"","frontmatter":{"title":"参数服务器对照","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/parameter-server-contrast.md","filePath":"llm/parameter-server-contrast.md","lastUpdated":1789023840000}'),P={name:"llm/parameter-server-contrast.md"};function m(S,e,c,h,u,E){const t=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=r('<h1 id="参数服务器对照" tabindex="-1">参数服务器对照 <a class="header-anchor" href="#参数服务器对照" aria-label="Permalink to &quot;参数服务器对照&quot;">​</a></h1><div class="epigraph"><p>All-Reduce 是对称的：每卡既是工人也是归约器。参数服务器把状态放到一组专用进程上，工人只推梯度、拉参数。稀疏更新喜欢后者，稠密 LLM 预训练几乎全体站在前者。</p><footer>—— Li 等 Parameter Server（OSDI 2014）；对照 DistBelief 与当代 DDP / ZeRO</footer></div><p><a href="/llm/gradient-compression">上一课</a> 在对称集体上减 \\(n\\)。本课对照另一条历史线：<strong>参数服务器（PS）</strong>。缺口是：为何 LLM 预训练默认 NCCL All-Reduce，而推荐、广告、部分 embedding 很大的系统仍在用 PS；以及把 PS 当「过时」会漏掉它仍然成立的通信形状。<a href="/llm/data-parallel-zero">数据并行与 ZeRO</a> 已经说明对称分片；本课只补不对称一侧，不重讲 ZeRO 档位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PS 架构：工人持数据与激活，服务器持分片参数。工人算完梯度，按键把非零项 push 到对应服务器，服务器更新后再 pull 新参数。通信是多对多的推拉，不是一次全局同步屏障。优点：天然稀疏——embedding 行只碰被命中的；服务器可以异步，工人不必等最慢的那个 All-Reduce。缺点：服务器带宽与 CPU/GPU 成为中心热点；稠密层每步几乎全量推拉，体积不比 All-Reduce 小，还多了中心化瓶颈；异步造成梯度陈旧，大模型不稳定。</p><p>LLM 预训练的主体是稠密矩阵，每步几乎所有参数都有梯度，稀疏度为零。此时 PS 的稀疏优势用不上，All-Reduce 的对称带宽（每卡 \\(\\frac{N-1}{N}n\\)）反而更好，且 <a href="/llm/rail-optimized-topology">轨优化</a> 就是为这种同步集体建的。问题是划清：<strong>哪一类张量该留在 PS 语义里</strong>。</p><p><span class="marginnote">DistBelief 与早期 Parameter Server 论文面对的是万亿稀疏特征，不是 70B 稠密 Transformer。把 2014 年的扩展数字直接写成 LLM 集群能力，是时代错位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>当代折中常见三种。</p><p>纯 All-Reduce / ZeRO：稠密 LLM 默认。集体库成熟，与 <a href="/llm/nvlink">NVLink</a> 层次化匹配。</p><p>混合：巨大词表或推荐 embedding 走 PS 或按键分片的异步更新，Transformer 主干走 DDP。两套进度要对齐到「同一 step 的语义」还是允许陈旧，是产品选择。</p><p>伪 PS：ZeRO-3 / FSDP 把参数片放在各 rank 上，需要时 all-gather——状态是分片的，通信仍是集体，没有专用服务器进程。它吃的是 All-Reduce 课的原语，不是 OSDI 那套 push/pull RPC。</p>',12)),(a(),n(A,null,{default:l(()=>[d(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20AR%5B%22%E5%AF%B9%E7%A7%B0%E9%9B%86%E4%BD%93%22%5D%0A%20%20%20%20W1%5B%22GPU%22%5D%20---%20W2%5B%22GPU%22%5D%0A%20%20end%0A%20%20subgraph%20PS%5B%22%E5%8F%82%E6%95%B0%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%0A%20%20%20%20WRK%5B%22%E5%B7%A5%E4%BA%BA%22%5D%20--%3E%20SRV%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%88%86%E7%89%87%22%5D%0A%20%20%20%20SRV%20--%3E%20WRK%0A%20%20end%0A%20%20DENSE%5B%22%E7%A8%A0%E5%AF%86%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20AR%0A%20%20SPARSE%5B%22%E7%A8%80%E7%96%8F%20embedding%20%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20PS%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>若坚持在稠密 LLM 上用 PS，至少把服务器也放在 GPU 上并走 RDMA，否则 PCIe 与 CPU 归约会成为墙。即便如此，同步屏障往往仍要加回来以保证收敛，那时你付了 PS 的中心化成本，又付了集体的等待，两头不讨好。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>All-Reduce 的一致性强：一步之后各副本权重一致（数值顺序差异除外）。PS 异步的一致性弱：工人用的参数可能差若干步。大 batch、大模型对陈旧梯度更敏感，这是 LLM 预训练弃异步 PS 的优化原因，不只是工程潮流。同步 PS（工人全部 push 完再更新再 pull）在通信量上不低于 All-Reduce，还把归约算力集中在服务器，扩展性更差。</p><p>稀疏梯度与 <a href="/llm/gradient-compression">梯度压缩</a> 的 Top-k 表面像，归属不同：Top-k 仍在对称集体上对齐索引；PS 按键路由，不需要全局对齐一张密张量。极度稀疏时，PS 的「只发非零」比先物化密梯度再压缩更省。稠密时相反。</p><p><span class="marginnote">推理服务的 KV 与权重加载不是 PS。不要把「参数在远端、算在本地」的任何系统都叫参数服务器。本课 PS 特指训练期的分片状态与推拉更新。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>本课不把 PS 写成必须淘汰。推荐系统、部分多模态的巨大词表、跨数据中心的联邦式更新，仍可能以 PS 为主。LLM 主干预训练、以及依赖 NCCL 的 Megatron 类网格，默认集体。不要在以太网集群上用 PS 去「避开」All-Reduce 的拥塞——你会换成服务器网卡拥塞，更难用轨优化建模。</p><p>集合通信课序到此收束算法与拓扑。下一课序转向集群运行：检查点 I/O 开始和集体抢同一张网。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PS 不对称、善稀疏与异步；All-Reduce 对称、善稠密同步。</li><li>LLM 预训练主体稠密，默认集体 + ZeRO，而不是 OSDI 式 PS。</li><li>混合架构只把真正稀疏的表放在 PS 语义里。</li><li>同步 PS 并不比 All-Reduce 更省带宽，还多中心瓶颈。</li><li>出处：Li 等 Parameter Server；DistBelief；对照当代 DDP / FSDP。</li></ul>',10))])}const D=o(P,[["render",m]]);export{f as __pageData,D as default};
